=== FILE: rr_arbiter.v ===
// rr_arbiter.v
// Round-robin arbiter for N requesters (default 4).
// Implements microarchitecture.md for interface_spec.md (rr_arbiter).
//
// State: one priority pointer `ptr` ($clog2(N) bits), reset to 0.
// Grant: combinational wrapping priority search from `ptr`, wrapping from
//        N-1 to 0 by comparison against LAST, so any N >= 2 works.
// Update: on a rising edge with a grant, ptr <= winner + 1 (wrapping);
//         with no request, ptr holds. rst_n is synchronous, active low.
`default_nettype none

module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer W        = (N > 1) ? $clog2(N) : 1;
    localparam integer LAST     = N - 1;
    localparam [W-1:0] PTR_ZERO = {W{1'b0}};
    localparam [W-1:0] PTR_ONE  = 1;

    reg [W-1:0] ptr;       // highest-priority requester this cycle
    reg [W-1:0] ptr_next;  // pointer after this cycle's grant
    reg [W-1:0] winner;    // index of the granted requester (valid if found)
    reg [W-1:0] cand;      // search candidate
    reg         found;     // a requester was granted this cycle
    integer     step;

    // Wrapping priority search: first requester at or after ptr.
    always @* begin
        found  = 1'b0;
        winner = PTR_ZERO;
        cand   = ptr;
        for (step = 0; step < N; step = step + 1) begin
            if (!found && req[cand]) begin
                found  = 1'b1;
                winner = cand;
            end
            if ({{(32-W){1'b0}}, cand} >= LAST) begin
                cand = PTR_ZERO;
            end else begin
                cand = cand + PTR_ONE;
            end
        end
        grant = {{(N-1){1'b0}}, found} << winner;
    end

    // Pointer update: one past the winner, wrapping at N; hold with no grant.
    always @* begin
        ptr_next = ptr;
        if (found) begin
            if ({{(32-W){1'b0}}, winner} >= LAST) begin
                ptr_next = PTR_ZERO;
            end else begin
                ptr_next = winner + PTR_ONE;
            end
        end
    end

    // Pointer register: synchronous active-low reset to 0.
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= PTR_ZERO;
        end else begin
            ptr <= ptr_next;
        end
    end

`ifdef FORMAL
    // Design-intent properties (interface_spec.md section 6).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    // Cyclic distance from one index to another, modulo N.
    function integer f_dist;
        input integer from_idx;
        input integer to_idx;
        begin
            if (to_idx >= from_idx) f_dist = to_idx - from_idx;
            else                    f_dist = to_idx + N - from_idx;
        end
    endfunction

    integer f_ptr;
    integer f_win;
    always @(*) begin
        f_ptr = {{(32-W){1'b0}}, ptr};
        f_win = {{(32-W){1'b0}}, winner};
    end

    always @(*) begin
        if (f_past_valid) begin
            // Pointer in range.
            assert(f_ptr <= LAST);
            // One-hot or zero.
            assert((grant & (grant - {{(N-1){1'b0}}, 1'b1})) == {N{1'b0}});
            // Only to a requester.
            assert((grant & ~req) == {N{1'b0}});
            // Work conserving.
            assert((req == {N{1'b0}}) || (grant != {N{1'b0}}));
            // Grant names the winner.
            if (found) assert(grant == ({{(N-1){1'b0}}, 1'b1} << winner));
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n))
                assert(ptr == PTR_ZERO);
            else if ($past(found))
                assert(f_ptr == (($past(f_win) == LAST) ? 0 : $past(f_win) + 1));
            else
                assert(ptr == $past(ptr));
        end
    end

    genvar gi;
    generate
        for (gi = 0; gi < N; gi = gi + 1) begin : g_formal
            reg [W:0] f_wait;  // cycles waited with the request held
            initial f_wait = {(W+1){1'b0}};
            always @(posedge clk) begin
                if (!rst_n || !req[gi] || grant[gi])
                    f_wait <= {(W+1){1'b0}};
                else
                    f_wait <= f_wait + 1'b1;
            end
            always @(*) begin
                if (f_past_valid) begin
                    // Induction invariant; implies wait <= N-1.
                    assert({{(31-W){1'b0}}, f_wait} + f_dist(f_ptr, gi) <= LAST);
                    // Round-robin order: nobody between ptr and the winner asks.
                    if (found && (f_dist(f_ptr, gi) < f_dist(f_ptr, f_win)))
                        assert(!req[gi]);
                end
            end
            always @(posedge clk) begin
                cover(f_past_valid && rst_n && grant[gi]);
            end
        end
    endgenerate

    always @(posedge clk) begin
        cover(f_past_valid && rst_n && (req == {N{1'b1}}));
        if (f_past_valid && $past(rst_n) && ($past(f_ptr) == LAST))
            cover(f_ptr == 0);
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
// rr_arbiter_tb.v
// Self-checking testbench for rr_arbiter, run at N=4 (default) and N=5
// (not a power of two). Each lane checks grant every cycle against a
// reference pointer model, measures per-requester waits against N-1, runs
// directed cases from interface_spec.md section 6 and fails the run if a
// required case is not reached. The top prints one verdict before $finish.

module rr_arbiter_tb_lane #(
    parameter integer N    = 4,
    parameter [31:0]  SEED = 32'h1A2B_3C4D
) (
    input  wire clk,
    output reg  done
);
    localparam [N-1:0] NONE = {N{1'b0}};
    localparam [N-1:0] ALL  = {N{1'b1}};
    localparam [N-1:0] ONE  = {{(N-1){1'b0}}, 1'b1};

    reg          rst_n;
    reg  [N-1:0] req;
    wire [N-1:0] grant;

    rr_arbiter #(.N(N)) dut (
        .clk  (clk),
        .rst_n(rst_n),
        .req  (req),
        .grant(grant)
    );

    // Control (driven by the stimulus process only).
    reg          checking;
    reg          clr;

    // Checker state (written by the checker process only).
    integer      c_passed;
    integer      c_failed;
    integer      ref_ptr;
    integer      waitc [0:N-1];
    integer      max_wait;
    integer      cov_none;
    integer      cov_all;
    integer      cov_rst_traffic;
    reg  [N-1:0] cov_alone;
    reg  [N-1:0] cov_granted;
    integer      ci;
    integer      cw;
    integer      cbits;
    reg  [N-1:0] cexp;

    // Stimulus state (written by the stimulus process only).
    integer      d_passed;
    integer      d_failed;
    integer      cov_held;
    integer      k;
    integer      h;
    integer      hw;
    reg  [31:0]  rng;
    reg  [N-1:0] stim;

    // Reference model: first requester at or after p, wrapping; -1 if none.
    function integer first_at;
        input [N-1:0] r;
        input integer p;
        integer s;
        integer c;
        begin
            first_at = -1;
            c = p;
            for (s = 0; s < N; s = s + 1) begin
                if (first_at < 0 && r[c] == 1'b1) first_at = c;
                if (c == N - 1) c = 0;
                else            c = c + 1;
            end
        end
    endfunction

    // ------------------------------------------------------------------
    // Checker: on every rising edge, compare against the model, then
    // advance the model exactly as the spec says.
    // ------------------------------------------------------------------
    always @(posedge clk) begin
        if (clr === 1'b1) begin
            c_passed        = 0;
            c_failed        = 0;
            ref_ptr         = 0;
            max_wait        = 0;
            cov_none        = 0;
            cov_all         = 0;
            cov_rst_traffic = 0;
            cov_alone       = NONE;
            cov_granted     = NONE;
        end

        cw = -1;
        if (checking === 1'b1) begin
            cw   = first_at(req, ref_ptr);
            cexp = NONE;
            if (cw >= 0) cexp = ONE << cw;

            // Round-robin order against the reference pointer model.
            if (grant === cexp) c_passed = c_passed + 1;
            else begin
                c_failed = c_failed + 1;
                $error("N=%0d t=%0t: grant %b, expected %b (req %b, model pointer %0d, rst_n %b)",
                       N, $time, grant, cexp, req, ref_ptr, rst_n);
            end

            // One-hot or zero.
            cbits = 0;
            for (ci = 0; ci < N; ci = ci + 1)
                if (grant[ci] === 1'b1) cbits = cbits + 1;
            if (cbits <= 1) c_passed = c_passed + 1;
            else begin
                c_failed = c_failed + 1;
                $error("N=%0d t=%0t: grant %b is not one-hot or zero", N, $time, grant);
            end

            // Only to a requester.
            if ((grant & ~req) === NONE) c_passed = c_passed + 1;
            else begin
                c_failed = c_failed + 1;
                $error("N=%0d t=%0t: grant %b to a requester not asking (req %b)", N, $time, grant, req);
            end

            // Work conserving.
            if (req === NONE || (|grant) === 1'b1) c_passed = c_passed + 1;
            else begin
                c_failed = c_failed + 1;
                $error("N=%0d t=%0t: req %b but no grant", N, $time, req);
            end

            // Coverage.
            if (rst_n === 1'b1 && req === NONE) cov_none = cov_none + 1;
            if (rst_n === 1'b1 && req === ALL)  cov_all  = cov_all + 1;
            if (rst_n === 1'b0 && req !== NONE) cov_rst_traffic = cov_rst_traffic + 1;
            if (rst_n === 1'b1) begin
                cov_granted = cov_granted | grant;
                for (ci = 0; ci < N; ci = ci + 1)
                    if (req === (ONE << ci)) cov_alone[ci] = 1'b1;
            end
        end

        // Fairness: no held request waits N cycles.
        for (ci = 0; ci < N; ci = ci + 1) begin
            if (checking !== 1'b1 || rst_n !== 1'b1 || req[ci] !== 1'b1 || grant[ci] === 1'b1) begin
                waitc[ci] = 0;
            end else begin
                waitc[ci] = waitc[ci] + 1;
                if (waitc[ci] > max_wait) max_wait = waitc[ci];
                if (waitc[ci] < N) c_passed = c_passed + 1;
                else begin
                    c_failed = c_failed + 1;
                    $error("N=%0d t=%0t: requester %0d has waited %0d cycles (bound %0d)",
                           N, $time, ci, waitc[ci], N - 1);
                end
            end
        end

        // Reference pointer update.
        if (rst_n !== 1'b1)  ref_ptr = 0;
        else if (cw >= 0)    ref_ptr = (cw == N - 1) ? 0 : cw + 1;
    end

    // ------------------------------------------------------------------
    // Stimulus helpers
    // ------------------------------------------------------------------
    task next_rng;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    // Drive one cycle at the falling edge, then let the logic settle.
    task drive;
        input         rn;
        input [N-1:0] r;
        begin
            @(negedge clk);
            rst_n = rn;
            req   = r;
            #1;
        end
    endtask

    task expect_grant;
        input [N-1:0] e;
        begin
            if (grant === e) d_passed = d_passed + 1;
            else begin
                d_failed = d_failed + 1;
                $error("N=%0d t=%0t: directed check: grant %b, expected %b (req %b, rst_n %b)",
                       N, $time, grant, e, req, rst_n);
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Stimulus
    // ------------------------------------------------------------------
    initial begin
        done     = 1'b0;
        checking = 1'b0;
        clr      = 1'b1;
        rst_n    = 1'b0;
        req      = NONE;
        d_passed = 0;
        d_failed = 0;
        cov_held = 0;
        hw       = 0;
        stim     = NONE;
        rng      = SEED;

        // Reset with no traffic, then start the reference model.
        drive(1'b0, NONE);
        clr = 1'b0;
        drive(1'b0, NONE);
        checking = 1'b1;
        drive(1'b0, NONE);
        expect_grant(NONE);

        // 1. No requests.
        for (k = 0; k < 3; k = k + 1) begin
            drive(1'b1, NONE);
            expect_grant(NONE);
        end

        // 2. Each requester alone.
        for (h = 0; h < N; h = h + 1) begin
            for (k = 0; k < 2; k = k + 1) begin
                drive(1'b1, ONE << h);
                expect_grant(ONE << h);
            end
        end

        // 3. Reset during traffic. Pointer is 0 here (last lone grant was N-1).
        drive(1'b1, ONE);            // requester 0 alone: pointer moves to 1
        expect_grant(ONE);
        drive(1'b0, ALL);            // reset sampled at this edge; pointer still 1
        expect_grant(ONE << 1);
        drive(1'b0, ALL);            // pointer is now 0; grant follows req in reset
        expect_grant(ONE);
        next_rng;
        drive(1'b0, rng[N-1:0] | (ONE << 1));
        drive(1'b0, ALL);            // pointer did not move during reset
        expect_grant(ONE);

        // 4. Everyone requesting: strict rotation 0, 1, ..., N-1 after reset.
        //    Requester N-1 waits N-1 cycles: the longest fair wait.
        for (k = 0; k < 3 * N; k = k + 1) begin
            drive(1'b1, ALL);
            expect_grant(ONE << (k % N));
        end

        // 5. A held request among changing others.
        for (h = 0; h < N; h = h + 1) begin
            hw = 0;
            for (k = 0; k < 4 * N; k = k + 1) begin
                next_rng;
                drive(1'b1, rng[N-1:0] | (ONE << h));
                if (grant[h] === 1'b1) begin
                    hw       = 0;
                    cov_held = cov_held + 1;
                    d_passed = d_passed + 1;
                end else begin
                    hw = hw + 1;
                    if (hw < N) d_passed = d_passed + 1;
                    else begin
                        d_failed = d_failed + 1;
                        $error("N=%0d t=%0t: held requester %0d waited %0d cycles (bound %0d)",
                               N, $time, h, hw, N - 1);
                    end
                end
            end
        end

        // 6. Random traffic at several densities, with a reset in the middle.
        for (k = 0; k < 400; k = k + 1) begin
            next_rng;
            case (rng[31:30])
                2'd0:    stim = rng[N-1:0] & rng[N+7:8];
                2'd1:    stim = rng[N-1:0] | rng[N+7:8];
                2'd2:    stim = rng[N-1:0];
                default: stim = ALL ^ (ONE << (rng[20:16] % N));
            endcase
            drive((k >= 200 && k < 203) ? 1'b0 : 1'b1, stim);
        end

        // 7. Quiet end.
        drive(1'b1, NONE);
        expect_grant(NONE);
        drive(1'b1, NONE);
        @(negedge clk);
        checking = 1'b0;

        // Coverage: every case the interface spec names must be reached.
        if (cov_none > 0) d_passed = d_passed + 1;
        else begin
            d_failed = d_failed + 1;
            $error("N=%0d: coverage: no-request case not reached", N);
        end
        if (cov_all > 0) d_passed = d_passed + 1;
        else begin
            d_failed = d_failed + 1;
            $error("N=%0d: coverage: everyone-requesting case not reached", N);
        end
        if (cov_alone === ALL) d_passed = d_passed + 1;
        else begin
            d_failed = d_failed + 1;
            $error("N=%0d: coverage: requester-alone cases reached only %b", N, cov_alone);
        end
        if (cov_granted === ALL) d_passed = d_passed + 1;
        else begin
            d_failed = d_failed + 1;
            $error("N=%0d: coverage: requesters granted only %b", N, cov_granted);
        end
        if (cov_rst_traffic > 0) d_passed = d_passed + 1;
        else begin
            d_failed = d_failed + 1;
            $error("N=%0d: coverage: reset during traffic not reached", N);
        end
        if (cov_held > 0) d_passed = d_passed + 1;
        else begin
            d_failed = d_failed + 1;
            $error("N=%0d: coverage: held request was never granted", N);
        end
        if (max_wait == N - 1) d_passed = d_passed + 1;
        else begin
            d_failed = d_failed + 1;
            $error("N=%0d: coverage: longest wait %0d, expected the fair maximum %0d", N, max_wait, N - 1);
        end

        done = 1'b1;
    end

endmodule

module rr_arbiter_tb;
    reg             clk;
    wire            done4;
    wire            done5;
    reg             timed_out;
    reg [8*64-1:0]  nonce;
    integer         passed;
    integer         failed;

    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    rr_arbiter_tb_lane #(.N(4), .SEED(32'h1A2B_3C4D)) u_n4 (.clk(clk), .done(done4));
    rr_arbiter_tb_lane #(.N(5), .SEED(32'h0BAD_F00D)) u_n5 (.clk(clk), .done(done5));

    initial begin
        timed_out = 1'b0;
        #200000;
        timed_out = 1'b1;
    end

    initial begin
        nonce  = {(8*64){1'b0}};
        passed = 0;
        failed = 0;
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {(8*64){1'b0}};

        wait ((done4 === 1'b1 && done5 === 1'b1) || timed_out === 1'b1);

        passed = u_n4.c_passed + u_n4.d_passed + u_n5.c_passed + u_n5.d_passed;
        failed = u_n4.c_failed + u_n4.d_failed + u_n5.c_failed + u_n5.d_failed;
        if (!(done4 === 1'b1 && done5 === 1'b1)) begin
            failed = failed + 1;
            $error("timeout: lanes did not finish (N=4 done %b, N=5 done %b)", done4, done5);
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
